from flask import Blueprint, abort

def route_join_with_or_without_slash(blueprint, route, *args, **kwargs):
    def decorator(f):
        blueprint.add_url_rule(route, view_func=f, *args, **kwargs)
        if not route.endswith('/'):
            blueprint.add_url_rule(route + '/', view_func=f, *args, **kwargs)
        return f
    return decorator

# Example usage:
blueprint = Blueprint('example_blueprint', __name__)

@route_join_with_or_without_slash(blueprint, '', methods=['GET'])
def index():
    abort(404)

@route_join_with_or_without_slash(blueprint, 'ls', methods=['GET'])
@route_join_with_or_without_slash(blueprint, 'ls', '<path:path>', methods=['GET'])
def ls(path=''):
    if not path.startswith('user://'):
        return abort(404)
```

